spec.expr:
sum by (result) (
  irate(
    gudit_inventory_stock_decrease_total{
      environment="performance"
    }[$__rate_interval]
  )
)
or label_replace(vector(0), "result", "success", "result", ".*")
or label_replace(vector(0), "result", "rejected", "result", ".*")
or label_replace(vector(0), "result", "failed", "result", ".*")

sum by (reason) (
  rate(
    gudit_inventory_stock_decrease_total{
      environment="performance",
      result="rejected"
    }[1m]
  )
)

histogram_quantile(
  0.95,
  sum by (le, script) (
    rate(
      gudit_inventory_lua_execution_seconds_bucket{
        environment="performance"
      }[1m]
    )
  )
) * 1000

sum(
  rate(
    http_server_requests_seconds_count{
      job="gudit",
      uri!~"/actuator.*"
    }[1m]
  )
) or vector(0)

(
  histogram_quantile(
    0.95,
    sum by (le) (
      rate(
        http_server_requests_seconds_bucket{
          job="gudit",
          uri!~"/actuator.*"
        }[5m]
      )
    )
  ) * 1000
) or vector(0)

(
  100 *
  sum(
    rate(
      http_server_requests_seconds_count{
        job="gudit",
        uri!~"/actuator.*",
        status=~"5.."
      }[5m]
    )
  )
  /
  clamp_min(
    sum(
      rate(
        http_server_requests_seconds_count{
          job="gudit",
          uri!~"/actuator.*"
        }[5m]
      )
    ),
    0.000001
  )
) or vector(0)

100 *
sum by (instance) (
  jvm_memory_used_bytes{
    job="gudit",
    area="heap"
  }
)
/
clamp_min(
  sum by (instance) (
    jvm_memory_max_bytes{
      job="gudit",
      area="heap"
    }
  ),
  1
)
